def main(argv=None):
    p = parser()
    args = p.parse_args(argv)
    if getattr(args,'task',None) is not None:
        with guard(args.task):return _dispatch(args,p)
    return _dispatch(args,p)


def _dispatch(args,p):
    import time
    from core.execution_context import session
    task=getattr(args,'task',None)
    started=time.monotonic()
    from core.workflow_profile import command_span
    with session(task),command_span(Path(task).resolve() if task else None,args.command,getattr(args,"operation",None)):
        try:
            return _dispatch_impl(args,p)
        finally:
            if task and (Path(task)/'state.json').is_file():
                from core.context_control import event,register_output
                output=getattr(args,'out',None)
                if output and Path(output).is_file():register_output(task,output)
                event(task,'command',args.command,seconds=time.monotonic()-started,detail={'inclusive':True})

def _dispatch_impl(args,p):
    if args.command=='presentation-backend':
        from core.presentation_backend import preferences
        from core.tool_router import capabilities
        if args.save_preferences:
            preferences(args.project,backend=args.backend,output_root=args.output_root)
        config={'render_preference':args.backend} if args.backend else None
        current=capabilities(config,args.project)
        result=current['presentation_backend']
        if args.refresh:
            from core.presentation_backend import select
            result=select(args.project,args.backend,refresh=True,libreoffice=current['libreoffice'] if current['libreoffice']['available'] else None)
        if args.out:write_json(args.out,result)
        print(json.dumps(result,ensure_ascii=False));return 0 if result.get('status')=='READY' else 2
    if args.command=='validate-presentation':
        from core.tool_router import capabilities,render_saved
        from core.presentation_backend import validate_delivery
        from core.office_compatibility import validate
        if args.out.exists():raise FileExistsError(args.out)
        args.out.mkdir(parents=True)
        caps=capabilities({'render_preference':args.backend},args.project)
        result={'package':validate(args.pptx),'render':render_saved(args.pptx,args.out/'render',caps,1440),
                'native_validation':validate_delivery(args.pptx,args.out,caps),'whole_drawing_acceptance':'NOT_RUN'}
        write_json(args.out/'Validation.json',result)
        print(json.dumps(result,ensure_ascii=False));return 0
    if args.command=='component-workflow':
        from core.component_workflow import dispatch
        if args.operation=='export':
            from core.component_workflow import export
            result=export(args.task,args.out,output_root=args.output_root,new_export=args.new_export)
        else:
            if args.out is None:raise ValueError('--out is required for non-export operations')
            result=dispatch(args.task,args.operation,read_json(args.request) if args.request else None)
            write_json(args.out,result)
        print(json.dumps({k:result[k] for k in ('status','components','component','count','ready') if k in result},ensure_ascii=False));return 0
    if args.command=='native-core':
        from core.native_core import command
        write_json(args.out,command(args.task,args.operation,read_json(args.request) if args.request else None))
        return
    if args.command=='formula-render':
        from core.portable_runtime import capabilities
        from core.portable_editor import render
        caps=capabilities(args.project)
        if caps['status']!='READY':
            write_json(args.out/'Capability.json',caps)
            return
        render(args.pptx,args.out,caps,width=args.width)
        return
    if args.command=='workflow-control':
        from core.workflow_control import dispatch
        from core.common import digest
        task_root=Path(args.task).resolve();output=Path(args.out).resolve()
        if not output.is_relative_to(task_root/'scratch')or output.exists():
            raise ValueError('Workflow reports require a fresh current-task scratch file')
        result=dispatch(args.task,args.operation,read_json(args.request) if args.request else None)
        write_json(args.out,result)
        summary={k:result[k] for k in ('status','schema','total','count','next_offset','counts','action_references') if k in result}
        summary['output']={'path':str(args.out),'sha256':digest(args.out)}
        summary['authority']='Finite guarded advancement or diagnosis; current next/submit and all quality gates remain mandatory.'
        print(json.dumps(summary,ensure_ascii=False));return 0
    if args.command=='batch':
        from core.batch_runtime import run
        task_root=Path(args.task).resolve();output=Path(args.out).resolve()
        if not output.is_relative_to(task_root/'scratch')or output.exists():
            raise ValueError('Batch receipt requires a fresh current-task scratch file')
        result=run(args.task,read_json(args.request));write_json(args.out,result)
        print(json.dumps({'status':result['status'],'report':str(args.out)},ensure_ascii=False));return
    if args.command in ('upgrade-task','compile-source-layers','source-text-repair'):
        if args.command=='upgrade-task':
            from core.task_migration import clone
            result=clone(args.source,args.destination)
        elif args.command=='compile-source-layers':
            from core.composition_program import bind
            result=bind(args.task,read_json(args.request))
        else:
            from core.source_text_actions import execute
            result=execute(args.task,read_json(args.request))
        write_json(args.out,result);print(json.dumps({'status':result.get('status','EXECUTED'),'report':str(args.out)},ensure_ascii=False));return 0
    if args.command=='runtime-bootstrap':
        from core.runtime_bootstrap import prepare
        result=prepare(args.project,args.bundle,args.native_libraries);write_json(args.out,result)
        print(json.dumps(__import__("core.state_repository",fromlist=["plain"]).plain(result),ensure_ascii=False));return 0
    if args.command=='source-detail':
        from core.adaptive_detail import command
        with guard(args.task):result=command(args.task,args.operation,read_json(args.request) if args.request else None)
        write_json(args.out,result);print(json.dumps({'status':result.get('status','SOURCE_DETAIL_PACKET'),'output':str(args.out)},ensure_ascii=False));return 0
    if args.command=='source-repeat':
        from core.source_repeat import command
        with guard(args.task):result=command(args.task,args.operation,read_json(args.request) if args.request else None)
        write_json(args.out,result);print(json.dumps({'status':result.get('status','SOURCE_REPEAT_PACKET'),'output':str(args.out)},ensure_ascii=False));return 0
    if args.command in ('recursive-check','connection-geometry','source-feature'):
        from core import agent_runtime as a,recursive_obligations as ro,connection_geometry as cg,quality_loop as ql,source_feature_functions as sf
        request=read_json(args.request) if args.request else None
        if args.command=='source-feature':
            if args.operation=='bind':result=sf.bind(args.task,request)
            else:
                task,state=a._state(args.task);result=sf.report(task,state,state.get('active_candidate') or state['selected'])
        elif args.command=='recursive-check':
            if args.operation=='plan':result=ro.bind_plan(args.task,request)
            elif args.operation=='execute':result=ro.execute_plan(args.task,request)
            else:result=ql.audit(args.task)['gates']['recursive_result_closure']
        else:
            if args.operation in ('survey','observe-source'):
                from core import source_connections as sc
                if args.operation=='observe-source':result=sc.observe(args.task,request)
                else:
                    task,state=a._state(args.task);result=sc.packet(task,state)
            elif args.operation=='bind':result=cg.bind(args.task,request)
            elif args.operation=='execute':result=cg.execute(args.task,request)
            else:
                task,state=a._state(args.task);candidate=state.get('active_candidate') or state['selected']
                result=cg.candidates(task,state,candidate) if args.operation=='discover' else cg.report(task,state,candidate)
        write_json(args.out,result);print(json.dumps({'status':result.get('status',result.get('passed')),'output':str(args.out)},ensure_ascii=False));return 0
    if args.command=='neighbor-check':
        from core import agent_runtime as a,neighbor_contracts as nc
        if args.operation=='bind':result=nc.bind(args.task,read_json(args.request))
        elif args.operation=='repair':
            from core.neighbor_actions import execute
            result=execute(args.task,read_json(args.request))
        else:
            task,state=a._state(args.task);candidate=state.get('active_candidate') or state['selected']
            if args.operation=='refresh-execution':result=nc.refresh_execution(task,state,candidate)
            elif args.operation=='capture':
                from core.neighbor_capture import capture_missing
                result=capture_missing(task,state,candidate)
            else:result=nc.prepare(task,state,candidate) if args.operation=='compile' else nc.repair_packet(task,state,candidate) if args.operation=='next' else nc.report(task,state,candidate)
            with a.writer(task):a._save(task,state)
        write_json(args.out,result);print(json.dumps({'status':(result or {}).get('status'),'output':str(args.out)},ensure_ascii=False));return 0
    if args.command in ('global-quality','object-loop'):
        from core import agent_runtime as a,global_aesthetic as ga,global_layout_actions as gl,object_lifecycle as ol,quality_loop as ql
        task,state=a._state(args.task);candidate=state.get('active_candidate') or state.get('selected')
        request=read_json(args.request) if args.request else None
        with guard(task):
            if args.command=='object-loop':
                if args.operation=='rollback':result=ol.rollback(task,request)
                elif args.operation=='discover-source':result=ol.owner_source_packet(task,state,candidate) or {'status':'CURRENT_NATIVE_SOURCE_TARGETS'}
                elif args.operation=='bind-source':result=ol.bind_owner_source(task,request)
                elif args.operation=='observations':result=ol.owner_observation_packet(task,state,candidate) or {'status':'CURRENT_NATIVE_OBSERVATIONS'}
                elif args.operation=='observe':result=ol.bind_owner_observations(task,request)
                else:result=ql.audit(task)['gates']['object_convergence']
            elif args.operation=='discover':result=ga.discover(task,state,candidate)
            elif args.operation=='bind':result=ga.bind(task,request)
            elif args.operation=='observe':result=ga.observe(task,request)
            elif args.operation=='observations':result=ga.packet(task,state,candidate) or {'status':'CURRENT_GLOBAL_OBSERVATIONS'}
            elif args.operation=='optimize':result=gl.execute(task,request)
